#!/usr/bin/env python3
"""Regenerate ground truth for CSX-176_Q1."""

from __future__ import annotations

import csv
import html
import json
import re
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-176_Q1"
EVENT_ID = "CSX-176"
DIFFICULTY_LEVEL = "L3"
TARGET_FAMILY = "report_anchor_score_ledger"

SOURCE_FILES = [
    "metadata/event.json",
    "metadata/files.csv",
    "data/event_reports/event_reports_003_Locked_event_anchor_2023_Greece_wildfires.json",
    "data/event_reports/event_reports_005_NASA_Earth_Observatory_wildfires_rage_in_Greece.html",
]


class TextBlockParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self._capture = False
        self._buf: list[str] = []
        self.blocks: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in {"p", "h1", "h2", "h3", "figcaption"}:
            self._capture = True
            self._buf = []

    def handle_endtag(self, tag: str) -> None:
        if tag in {"p", "h1", "h2", "h3", "figcaption"} and self._capture:
            text = " ".join("".join(self._buf).split())
            if text:
                self.blocks.append(text)
            self._capture = False
            self._buf = []

    def handle_data(self, data: str) -> None:
        if self._capture:
            self._buf.append(data)


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_dir() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(package: Path, rel_path: str) -> Any:
    return json.loads((package / rel_path).read_text(encoding="utf-8-sig"))


def require_manifest_paths(package: Path, rel_paths: list[str]) -> None:
    with (package / "metadata" / "files.csv").open(newline="", encoding="utf-8-sig") as handle:
        manifest_paths = {row["relative_path"] for row in csv.DictReader(handle)}
    for rel_path in rel_paths:
        if rel_path.startswith("metadata/"):
            continue
        if rel_path not in manifest_paths:
            raise ValueError(f"Input file is not listed in metadata/files.csv: {rel_path}")


def html_blocks(path: Path) -> tuple[str, list[str]]:
    text = path.read_text(encoding="utf-8", errors="ignore")
    parser = TextBlockParser()
    parser.feed(text)
    return text, parser.blocks


def first_matching(blocks: list[str], pattern: str) -> str:
    rx = re.compile(pattern, re.IGNORECASE)
    for block in blocks:
        if rx.search(block):
            return block
    return ""


def plain_text_from_html(raw_html: str) -> str:
    without_tags = re.sub(r"<[^>]+>", " ", raw_html)
    return " ".join(html.unescape(without_tags).split())


def first_matching_text(text: str, pattern: str) -> str:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    return match.group(0) if match else ""


def iso_date_from_report(raw_html: str, blocks: list[str]) -> str:
    if re.search(r"2023-08-22\s+00:00:00", raw_html):
        return "2023-08-22"
    if any(re.fullmatch(r"August 22, 2023", block) for block in blocks):
        return "2023-08-22"
    return ""


def compact_json_size(value: Any) -> int:
    return len(json.dumps(value, ensure_ascii=True, separators=(",", ":")))


def pretty_json_size(value: Any) -> int:
    return len(json.dumps(value, ensure_ascii=True, indent=2).encode("utf-8"))


def main() -> None:
    package = package_dir()
    require_manifest_paths(package, SOURCE_FILES)

    event = read_json(package, "metadata/event.json")
    anchor = read_json(
        package,
        "data/event_reports/event_reports_003_Locked_event_anchor_2023_Greece_wildfires.json",
    )

    if event.get("package_id") != EVENT_ID:
        raise ValueError("Unexpected package_id in metadata/event.json")
    if event.get("hazard_family") != "wildfire_burn_smoke":
        raise ValueError("Unexpected hazard family")

    report_path = package / "data/event_reports/event_reports_005_NASA_Earth_Observatory_wildfires_rage_in_Greece.html"
    raw_html, blocks = html_blocks(report_path)
    plain_text = plain_text_from_html(raw_html)

    report_claims = {
        "late_august_fires": first_matching(blocks, r"dozens more fires ignited within 24 hours"),
        "alexandroupolis_plume": first_matching(blocks, r"Alexandroupolis.*plume.*southwest toward Italy"),
        "athens_local_impact": first_matching(blocks, r"Athens.*homes.*cars.*smoke"),
        "fire_weather_aug23": first_matching(blocks, r"extreme fire weather.*hot, dry, and windy.*August 23"),
        "mediterranean_smoke": first_matching(blocks, r"smoke was detected.*Italy.*northern Africa"),
        "annual_burned_area_context": (
            first_matching(blocks, r"area burned in Greece so far in 2023.*2021 fire season")
            or first_matching_text(plain_text, r"area burned in Greece so far in 2023 has surpassed[^.]*2021 fire season")
        ),
    }

    image_date = iso_date_from_report(raw_html, blocks)
    weather_smoke_context_date = "2023-08-23" if report_claims["fire_weather_aug23"] else ""

    active_flags = {
        "late_august_fires_24h": bool(report_claims["late_august_fires"]),
        "alexandroupolis_plume_toward_italy": bool(report_claims["alexandroupolis_plume"]),
        "satellite_image_date": image_date == "2023-08-22",
        "hot_dry_windy_fire_weather_aug23": bool(report_claims["fire_weather_aug23"]),
        "italy_northern_africa_smoke": bool(report_claims["mediterranean_smoke"]),
    }
    comparison_flags = {
        "annual_burned_area_context": bool(report_claims["annual_burned_area_context"]),
        "athens_homes_cars_smoke": bool(report_claims["athens_local_impact"]),
    }

    score_ledger = {
        "late_august_active_fire_smoke": int(sum(active_flags.values())),
        "annual_burned_area_context": int(comparison_flags["annual_burned_area_context"]),
        "athens_only_local_fire": int(comparison_flags["athens_homes_cars_smoke"]),
    }

    if score_ledger["late_august_active_fire_smoke"] >= 4:
        answer = "late_august_active_fire_smoke_phase"
    elif score_ledger["annual_burned_area_context"] > score_ledger["athens_only_local_fire"]:
        answer = "annual_burned_area_context"
    else:
        answer = "athens_only_local_fire_phase"

    date_ledger = {
        "image_date": image_date,
        "weather_smoke_context_date": weather_smoke_context_date,
    }
    anchor_ledger = [
        "dozens_more_fires_within_24h",
        "alexandroupolis_plume_toward_italy",
        "satellite_image_2023_08_22",
        "hot_dry_windy_fire_weather_2023_08_23",
        "smoke_over_italy_and_northern_africa",
        "athens_homes_cars_smoke_context",
        "annual_burned_area_surpassed_2021_context",
    ]

    primary_gt = {
        "answer": answer,
        "dates": date_ledger,
        "scores": score_ledger,
        "anchors": anchor_ledger,
        "comparison_rule": "use highest phase score; active_fire_smoke wins at >=4/5",
        "tolerances": {"dates": "exact", "scores": 0},
        "stance": "Late-August phase is active-fire/smoke transport; annual burned-area and Athens anchors are context.",
    }

    if len(primary_gt) > 8 or compact_json_size(primary_gt) > 1200:
        raise ValueError("primary_gt must remain compact")

    rubric_criteria = [
        {
            "name": "canonical_label",
            "points": 3,
            "description": "Returns late_august_active_fire_smoke_phase as the final canonical label.",
            "partial_credit": "Credit an equivalent active-fire/smoke phase label with wording differences.",
        },
        {
            "name": "date_ledger",
            "points": 3,
            "description": "Reports image_date 2023-08-22 and weather_smoke_context_date 2023-08-23.",
            "partial_credit": "Credit one correct date or correct dates with non-ISO formatting.",
        },
        {
            "name": "active_fire_smoke_score",
            "points": 4,
            "description": "Computes late_august_active_fire_smoke = 5 from all five requested anchors.",
            "partial_credit": "Credit a score of 3 or 4 when the omitted anchors are clear.",
        },
        {
            "name": "comparison_scores",
            "points": 3,
            "description": "Computes annual_burned_area_context = 1 and athens_only_local_fire = 1.",
            "partial_credit": "Credit recognition of either comparison anchor alone.",
        },
        {
            "name": "anchor_specificity",
            "points": 3,
            "description": (
                "Names at least three specific anchors among late-August fires, Alexandroupolis-to-Italy plume, "
                "hot/dry/windy fire weather, Italy/northern Africa smoke, and Athens homes/cars/smoke."
            ),
            "partial_credit": "Credit one or two specific anchors; reduce for generic wildfire-only wording.",
        },
        {
            "name": "score_based_interpretation",
            "points": 2,
            "description": "Explains that the five-anchor score selects the active-fire/smoke code over comparison codes.",
            "partial_credit": "Credit the correct label without explicit score comparison.",
        },
        {
            "name": "output_structure",
            "points": 2,
            "description": "Returns compact JSON-like fields and avoids adding casualty, health-burden, or national damage totals.",
            "partial_credit": "Credit correct content delivered in prose rather than the requested structure.",
        },
    ]

    computed_gt = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "task_subtype": "late_august_wildfire_smoke_score_ledger",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": DIFFICULTY_LEVEL,
        "event": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": (
                f"{anchor['temporal_window']['start_date']} to {anchor['temporal_window']['end_date']}"
            ),
        },
        "primary_gt": primary_gt,
        "key_values": {
            "date_ledger": date_ledger,
            "score_ledger": score_ledger,
            "active_flags": active_flags,
            "comparison_flags": comparison_flags,
            "report_claims": report_claims,
        },
        "required_findings": [
            "Extract 2023-08-22 as the satellite image date.",
            "Extract 2023-08-23 as the hot/dry/windy fire-weather and smoke context date.",
            "Count all five active-fire/smoke anchors as present.",
            "Treat annual burned-area comparison and Athens impacts as one-point context anchors.",
        ],
        "forbidden_claims": [
            "Do not add casualty, hospital, smoke-dose, structure-loss, or national damage totals as computed outputs.",
            "Do not collapse the result to Athens-only when the five-anchor active-fire/smoke score is present.",
        ],
        "rubric": {
            "total_points": 20,
            "criteria": rubric_criteria,
        },
        "quality_audit": {
            "primary_gt_key_count": len(primary_gt),
            "primary_gt_compact_json_bytes": compact_json_size(primary_gt),
            "primary_gt_pretty_json_bytes": pretty_json_size(primary_gt),
            "rubric_points": sum(item["points"] for item in rubric_criteria),
            "response_advice_centered": False,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }

    output_path = Path(__file__).resolve().parent / "computed_gt.json"
    output_path.write_text(json.dumps(computed_gt, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
